const historyRegions = [
  'Middle East',
  'Europe',
  'South Asia',
  'East Asia',
  'Sub-Saharan Africa',
  'pre-colonial Americas',
  'the Steppe'
];

const MARGIN = { top: 12, right: 14, bottom: 44, left: 14 };
const ROW = 15;
const BAR = 11;
const FONT = 10;
// Mean advance width of the gallery sans-serif as a fraction of font size; there is no DOM
// to measure real text boxes at layout time.
const CHAR_WIDTH = 0.55;
const GAP = 6;
const LEGEND_ROW = 18;
const SPAN: [number, number] = [-3500, 2018];

const formatYear = (year: number) => (year < 0 ? `${-year} BC` : `AD ${year}`);

type Placed = Civilization & {
  x0: number;
  x1: number;
  lane: number;
  labelAt: 'inside' | 'right' | 'left' | 'none';
};

/**
 * Spans in years (negative is BC), pre-sorted by `start` because the lane packer is greedy,
 * plus the region list the legend and the colour scale enumerate.
 */
export type Data = {
  civilizations: { civilization: string; start: number; end: number; region: string }[];
  regions: string[];
};

const DEMO: Data = { civilizations, regions: historyRegions };

export default function WorldHistoryTimeline({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const innerWidth = Math.max(0, width - MARGIN.left - MARGIN.right);

  const x = useMemo(() => d3.scaleLinear().domain(SPAN).range([0, innerWidth]), [innerWidth]);

  const color = useMemo(
    () => d3.scaleOrdinal<string, string>().domain(data.regions).range(d3.schemeObservable10),
    [data]
  );

  // Greedy first-fit lane packing: walk the spans in start order and drop each into the first
  // lane whose occupied extent has already ended. The label, not the bar, sets that extent.
  const { rows, laneCount } = useMemo(() => {
    const laneEnds: number[] = [];
    const packed = data.civilizations.map((d): Placed => {
      const x0 = x(d.start);
      const x1 = x(d.end);
      const textWidth = d.civilization.length * FONT * CHAR_WIDTH;
      let labelAt: Placed['labelAt'] = 'none';
      let occupiedStart = x0;
      let occupiedEnd = x1;
      if (x1 - x0 >= textWidth + 8) {
        labelAt = 'inside';
      } else if (x1 + GAP + textWidth <= innerWidth) {
        labelAt = 'right';
        occupiedEnd = x1 + GAP + textWidth;
      } else if (x0 - GAP - textWidth >= 0) {
        labelAt = 'left';
        occupiedStart = x0 - GAP - textWidth;
      }
      let lane = laneEnds.findIndex((end) => end <= occupiedStart - 2);
      if (lane < 0) lane = laneEnds.push(0) - 1;
      laneEnds[lane] = occupiedEnd;
      return { ...d, x0, x1, lane, labelAt };
    });
    return { rows: packed, laneCount: laneEnds.length };
  }, [data, x, innerWidth]);

  const legend = useMemo(() => {
    let cursorX = 0;
    let line = 0;
    const items = data.regions.map((region) => {
      const itemWidth = 14 + region.length * 11 * CHAR_WIDTH + 14;
      if (cursorX > 0 && cursorX + itemWidth > innerWidth) {
        cursorX = 0;
        line += 1;
      }
      const placed = { region, x: cursorX, y: line * LEGEND_ROW };
      cursorX += itemWidth;
      return placed;
    });
    return { items, height: (line + 1) * LEGEND_ROW };
  }, [data, innerWidth]);

  const innerHeight = laneCount * ROW;
  const height = MARGIN.top + legend.height + 8 + innerHeight + MARGIN.bottom;
  const laneTop = MARGIN.top + legend.height + 8;

  const ticks: Tick[] = useMemo(
    () => x.ticks(innerWidth < 480 ? 5 : 9).map((v) => ({ value: formatYear(v), offset: x(v) })),
    [x, innerWidth]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Timeline of ${data.civilizations.length} major civilizations from 3500 BC to the present, coloured by region. Overlapping spans are packed greedily into ${laneCount} rows so each row holds only non-overlapping intervals. Date ranges adapted from Essential Humanities' world history timeline.`}
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {legend.items.map((item) => (
          <g key={item.region} transform={`translate(${item.x},${item.y})`}>
            <rect x={0} y={2} width={9} height={9} rx={2} fill={color(item.region)} />
            <text x={14} y={7} dy="0.32em" fontSize={11} fill="var(--muted)">
              {item.region}
            </text>
          </g>
        ))}
      </g>
      <g transform={`translate(${MARGIN.left},${laneTop})`}>
        <g className="axis">
          {ticks.map((t) => (
            <line key={t.value} className="grid" x1={t.offset} x2={t.offset} y1={0} y2={innerHeight} />
          ))}
        </g>
        {rows.map((d) => (
          <rect
            key={d.civilization}
            x={d.x0}
            y={d.lane * ROW}
            width={Math.max(1, d.x1 - d.x0)}
            height={BAR}
            rx={2}
            fill={color(d.region)}
          />
        ))}
        {rows
          .filter((d) => d.labelAt !== 'none')
          .map((d) => (
            <text
              key={`label-${d.civilization}`}
              x={d.labelAt === 'inside' ? d.x0 + 4 : d.labelAt === 'right' ? d.x1 + GAP : d.x0 - GAP}
              y={d.lane * ROW + BAR / 2}
              dy="0.32em"
              fontSize={FONT}
              textAnchor={d.labelAt === 'left' ? 'end' : 'start'}
              fill={d.labelAt === 'inside' ? 'var(--panel)' : 'var(--text)'}
            >
              {d.civilization}
            </text>
          ))}
        <AxisBottom ticks={ticks} height={innerHeight} width={innerWidth} />
        {innerWidth >= 480 && (
          <text x={0} y={innerHeight + 36} fontSize={11} fill="var(--muted)">
            Date ranges adapted from Essential Humanities&rsquo; world history timeline.
          </text>
        )}
      </g>
    </svg>
  );
}
